/**
 * Package unit/type contract for the mechanical tool and turn-data extraction.
 * Independent sequence digests are frozen from Git 87542c8: literal tool order
 * and ActionWindow/KnightDuelWindow-expanded stage order. Type counterexamples
 * preserve nullable, readonly and discriminated argument contracts. No runtime
 * provider, request lease, role resolver or gameplay authority is executed here.
 */
import { expect, test } from "bun:test";
import { createHash } from "node:crypto";
import {
  TOOL_NAMES,
  ACTION_STAGES,
  DEATH_SHOT_STAGES,
  type ToolName,
  type ToolArgMap,
  type ToolCall,
  type TypedToolCall,
  type ToolValidationResult,
  type TurnConstraints,
} from "@ai-werewolf-arena/game-contract/actions";
import {
  PotionType,
  TOOL_NAMES as rootTools,
  ACTION_STAGES as rootStages,
  DEATH_SHOT_STAGES as rootDeathStages,
} from "@ai-werewolf-arena/game-contract";
// @ts-expect-error A callable runtime provider is not serialized tool/turn data.
import type { ActionProvider } from "@ai-werewolf-arena/game-contract";

const digest = (values: readonly string[]) =>
  createHash("sha256").update(JSON.stringify(values)).digest("hex");

test("65 tool IDs and 82 runtime stages retain the exact frozen sequence and public singleton", () => {
  expect(TOOL_NAMES).toHaveLength(65);
  expect(digest(TOOL_NAMES)).toBe(
    "55594da0f2ee11b46ed5004b26bcaca6bca9d213360e8bf2f1bf96b6a12807e2",
  );
  expect(ACTION_STAGES).toHaveLength(82);
  expect(digest(ACTION_STAGES)).toBe(
    "470508b488c62e83ad98065268578354f3bf333f68ae6591b57bfc9cec54c317",
  );
  expect(DEATH_SHOT_STAGES).toEqual(["hunter_shot", "death_shot"]);
  expect(TOOL_NAMES).toBe(rootTools);
  expect(ACTION_STAGES).toBe(rootStages);
  expect(DEATH_SHOT_STAGES).toBe(rootDeathStages);
  // Original readonly types did not freeze their runtime arrays.
  expect(Object.isFrozen(TOOL_NAMES)).toBe(false);
  expect(Object.isFrozen(ACTION_STAGES)).toBe(false);
});

test("tool discriminants retain nullable passes, readonly pairs and nominal potion values", () => {
  const vote: TypedToolCall<"vote"> = { name: "vote", args: { target_id: null, abstain: true } };
  const pair: ToolArgMap["check_pair"] = { target_ids: [1, 2] };
  const potion: ToolCall = {
    name: "use_potion",
    args: { target_id: 1, potion_type: PotionType.None },
  };
  const validation: ToolValidationResult<typeof vote> = { ok: true, sanitizedCall: vote };
  // @ts-expect-error Unknown tools do not enter the closed tool union.
  const unknown: ToolName = "invented_tool";
  // @ts-expect-error A required inspection target cannot become a pass.
  const noTarget: ToolArgMap["check_identity"] = { target_id: null };
  // @ts-expect-error Typed vote calls cannot silently select another tool.
  const wrongTool: TypedToolCall<"vote"> = { name: "shoot", args: { target_id: 1 } };
  // @ts-expect-error Potion args keep their existing enum type.
  const rawPotion: ToolArgMap["use_potion"] = { target_id: 1, potion_type: "none" };
  if (false) {
    // @ts-expect-error The pair tuple remains readonly through the tool contract.
    pair.target_ids[0] = 3;
  }
  void [unknown, noTarget, wrongTool, rawPotion];
  expect(vote).toEqual({ name: "vote", args: { target_id: null, abstain: true } });
  expect(potion).toEqual({
    name: "use_potion",
    args: { target_id: 1, potion_type: PotionType.None },
  });
  expect(validation.sanitizedCall).toBe(vote);
});

test("optional turn constraints retain raw summary and a closed MessageRef without adding policy", () => {
  const empty: TurnConstraints = {};
  const raw: TurnConstraints = { summary: "Custom original {role}" };
  const structured: TurnConstraints = {
    required_any_tools: ["speak"],
    summary_message: { key: "common.player", parameters: { id: 12 } },
  };
  // @ts-expect-error Structured summaries keep the full closed machine key set.
  const unknownKey: TurnConstraints = { summary_message: { key: "invented_message" } };
  // @ts-expect-error Required tools keep the closed tool ID union.
  const unknownTool: TurnConstraints = { required_any_tools: ["invented_tool"] };
  void [unknownKey, unknownTool];
  expect(empty).toEqual({});
  expect(raw.summary).toBe("Custom original {role}");
  expect(structured).toEqual({
    required_any_tools: ["speak"],
    summary_message: { key: "common.player", parameters: { id: 12 } },
  });
});

/**
 * Package unit/type contract for serialized board shapes and policy identifiers.
 * Literal configurations, malformed inert inputs and readonly DTO type errors
 * are independent oracles. Shape parsing preserves bounds and optional fields;
 * these tests never invoke finite-board support, rule algorithms, World storage
 * or model transports. A parsed board alone grants no execution authority.
 */
import { expect, test } from "bun:test";
import {
  Role,
  Camp,
  WinCondition,
  ANIMAL_DREAM_POLICY,
  NIGHTMARE_SHADOW_POLICY,
  EVIL_KNIGHT_POLICY,
  PURE_WHITE_POLICY,
  CAT_SKIPPED_VOTE_POLICIES,
  PUFFER_BALLOT_POLICIES,
  BEAR_SIGNAL_POLICIES,
  DEFAULT_SEER_ACTION_POLICY,
  type BoardConfig,
  type LoversComponent,
} from "@ai-werewolf-arena/game-contract";
import { boardConfigSchema } from "@ai-werewolf-arena/game-contract/board-schema";
import { EVENT_PACK_IDS } from "@ai-werewolf-arena/game-contract/boards";

function classic(): BoardConfig {
  return {
    boardSize: 6,
    enableSheriff: false,
    roleSetups: [
      { role: Role.Wolf, count: 2 },
      { role: Role.Seer, count: 1 },
      { role: Role.Villager, count: 3 },
    ],
    hooks: {
      onDaybreak: false,
      onPreElection: false,
      onPreVote: false,
      onPerSpeechGap: false,
    },
  };
}

test("literal six-seat shape and empty optional objects acquire no defaults", () => {
  const raw = classic();
  expect(boardConfigSchema.parse(raw)).toEqual(raw);
  const optionals = { ...raw, sheriff: {}, witch: {}, tieBreaker: {} };
  expect(boardConfigSchema.parse(optionals)).toEqual(optionals);
  expect(Object.hasOwn(boardConfigSchema.parse(raw), "seer")).toBe(false);
  expect(Object.hasOwn(boardConfigSchema.parse(raw), "winConditions")).toBe(false);
  expect(DEFAULT_SEER_ACTION_POLICY).toBe("awa_required_when_legal_v1");
});

test("shape-only integer endpoints and empty goals preserve the independent support boundary", () => {
  const maximum = { ...classic(), boardSize: 128, roleSetups: [{ role: Role.Wolf, count: 128 }] };
  expect(boardConfigSchema.parse(maximum)).toEqual(maximum);
  const structural = {
    ...classic(),
    roleSetups: [
      { role: Role.Wolf, count: 0 },
      { role: Role.Wolf, count: 1 },
    ],
    winConditions: [],
  };
  // The existing schema does not sum the deck, deduplicate roles or apply a goal.
  expect(boardConfigSchema.parse(structural)).toEqual(structural);
});

test("required fields, strict tails, role minimum and count bounds reject unchanged", () => {
  const base = classic();
  const { enableSheriff: _required, ...missing } = base;
  for (const input of [
    missing,
    { ...base, privateState: {} },
    { ...base, boardSize: 0 },
    { ...base, boardSize: 129 },
    { ...base, boardSize: 1.5 },
    { ...base, roleSetups: [] },
    { ...base, roleSetups: [{ role: Role.Wolf, count: -1 }] },
    { ...base, roleSetups: [{ role: Role.Wolf, count: 129 }] },
    { ...base, roleSetups: [{ role: Role.Wolf, count: 1.5 }] },
    { ...base, roleSetups: [{ role: Role.Wolf, count: 2, hidden: true }] },
    { ...base, hooks: { ...base.hooks, extra: true } },
    { ...base, seer: { targetPolicy: "awa_alive_v1" } },
  ])
    expect(boardConfigSchema.safeParse(input).success).toBe(false);
});

test("runtime Role enum remains the 55-member schema boundary while raw JSON IDs still parse", () => {
  const raw = JSON.parse(JSON.stringify(classic()));
  expect(boardConfigSchema.parse(raw).roleSetups[0]!.role).toBe(Role.Wolf);
  expect(Object.values(Role)).toHaveLength(55);
  for (const role of ["awakened_knight", "unregistered_role", "Wolf"])
    expect(boardConfigSchema.safeParse({ ...raw, roleSetups: [{ role, count: 1 }] }).success).toBe(
      false,
    );
});

test("finite-number and option enum errors retain the original strict-shape policy", () => {
  const base = classic();
  for (const voteWeight of [0, -1, Infinity, NaN, "1.5"])
    expect(boardConfigSchema.safeParse({ ...base, sheriff: { voteWeight } }).success).toBe(false);
  expect(
    boardConfigSchema.parse({ ...base, sheriff: { voteWeight: 1.5 } }).sheriff?.voteWeight,
  ).toBe(1.5);
  expect(boardConfigSchema.safeParse({ ...base, winCondition: "unknown_goal" }).success).toBe(
    false,
  );
  expect(
    boardConfigSchema.parse({ ...base, winCondition: WinCondition.SlaughterSide }).winCondition,
  ).toBe(WinCondition.SlaughterSide);
  expect(
    boardConfigSchema.safeParse({ ...base, bear: { signalPolicy: "unknown_policy" } }).success,
  ).toBe(false);
});

test("four policy constants and three ordered arrays keep their original literal and mutability API", () => {
  expect(ANIMAL_DREAM_POLICY).toBe("awa_animal_dream_v1");
  expect(NIGHTMARE_SHADOW_POLICY).toBe("awa_nightmare_dreamer_v1");
  expect(EVIL_KNIGHT_POLICY).toBe("awa_evil_knight_v1");
  expect(PURE_WHITE_POLICY).toBe("awa_pure_white_night_v1");
  expect(CAT_SKIPPED_VOTE_POLICIES).toEqual([
    "awa_wait_for_actual_exile_v1",
    "awa_expire_on_skipped_day_v1",
  ]);
  expect(PUFFER_BALLOT_POLICIES).toEqual(["awa_final_ballot_v1", "awa_first_ballot_v1"]);
  expect(BEAR_SIGNAL_POLICIES).toEqual(["awa_night_open_v1", "netease_dawn_live_v1"]);
  for (const array of [CAT_SKIPPED_VOTE_POLICIES, PUFFER_BALLOT_POLICIES, BEAR_SIGNAL_POLICIES])
    expect(Object.isFrozen(array)).toBe(false);
  expect(EVENT_PACK_IDS).toEqual(["awa_wall_notes_once_v1"]);
});

test("Cupid DTO remains readonly God metadata with enum camps and no runtime handles", () => {
  const relation: LoversComponent = {
    actorId: 7,
    day: 1,
    policy: "netease_2017_cupid_follows_lovers_v1",
    pairIds: [2, 3],
    pairCamps: [Camp.Good, Camp.Wolf],
    groupId: "cupid_lovers",
    mixed: true,
  };
  if (false) {
    // @ts-expect-error Metadata actor identity stays readonly.
    relation.actorId = 8;
    // @ts-expect-error Pair tuples stay readonly.
    relation.pairIds[0] = 8;
    // @ts-expect-error Cupid has the original first-night data unit.
    const laterDay: LoversComponent["day"] = 2;
    // @ts-expect-error Relation camps preserve the original nominal enum subset.
    const thirdParty: LoversComponent["pairCamps"] = [Camp.Good, Camp.ThirdParty];
    // @ts-expect-error String labels do not replace the Camp member types.
    const rawCamps: LoversComponent["pairCamps"] = ["good", "wolf"];
    void [laterDay, thirdParty, rawCamps];
  }
  expect(JSON.parse(JSON.stringify(relation))).toEqual({
    actorId: 7,
    day: 1,
    policy: "netease_2017_cupid_follows_lovers_v1",
    pairIds: [2, 3],
    pairCamps: ["good", "wolf"],
    groupId: "cupid_lovers",
    mixed: true,
  });
});

/**
 * Package unit/type contract for the event and request DTO ownership move.
 * Literal expected IDs and payloads verify public data shapes and the original
 * conditional audience, required context and optional feature fields. Type
 * counterexamples check declared constraints without running an engine, provider
 * or lease. The projected payload stays open; these types never parse unknown
 * data, prove permissions or promise hostile-object rejection at runtime.
 */
import { expect, test } from "bun:test";
import {
  WOLF_TEAM_EVENT_TYPES,
  type GameEvent,
  type EventPayloadMap,
  type PlayerVisibleEvent,
} from "@ai-werewolf-arena/game-contract/events";
import type {
  ActionRequest,
  ActionRequestContext,
  ActionRequestExtras,
} from "@ai-werewolf-arena/game-contract/requests";
import {
  Camp,
  Phase,
  WOLF_TEAM_EVENT_TYPES as rootWolfEvents,
  type LoversComponent,
} from "@ai-werewolf-arena/game-contract";
// @ts-expect-error Runtime decision providers remain outside serialized contracts.
import type { ActionProvider } from "@ai-werewolf-arena/game-contract";
// @ts-expect-error Domain commit selections have not moved into the public request DTO.
import type { KnightDuelSelection } from "@ai-werewolf-arena/game-contract/requests";

test("the public wolf sequence retains its exact order, singleton and original mutability", () => {
  expect(WOLF_TEAM_EVENT_TYPES).toEqual([
    "mist_knife_drawn",
    "wolf_tactical_order",
    "wolf_discussion",
    "wolf_discussion_ended",
    "wolf_kill_vote_cast",
  ]);
  expect(WOLF_TEAM_EVENT_TYPES).toBe(rootWolfEvents);
  expect(Object.isFrozen(WOLF_TEAM_EVENT_TYPES)).toBe(false);
});

test("event discrimination preserves private readonly audience and public Animal reveals", () => {
  type Fear = Extract<GameEvent, { type: "nightmare_fear_committed" }>;
  const fear: Fear = {
    timestamp: 1,
    type: "nightmare_fear_committed",
    payload: { actorId: 2, day: 1, targetId: null },
    audience: [2],
  };
  // @ts-expect-error A private event must retain its explicit historical audience.
  const noAudience: Fear = {
    timestamp: 1,
    type: "nightmare_fear_committed",
    payload: { actorId: 2, day: 1, targetId: null },
  };
  const wrongPayload: Fear = {
    timestamp: 1,
    type: "nightmare_fear_committed",
    // @ts-expect-error A payload belonging to a different event is not a fear choice.
    payload: { playerId: 2, day: 1 },
    audience: [2],
  };
  // @ts-expect-error Private Animal contributions retain required audience through the extended map.
  const noFoxAudience: Extract<GameEvent, { type: "animal_fox_chosen" }> = {
    timestamp: 1,
    type: "animal_fox_chosen",
    payload: { policy: "awa_animal_dream_v1", actorId: 2, day: 1, targetId: null },
  };
  const cat: Extract<GameEvent, { type: "animal_cat_revealed" }> = {
    timestamp: 2,
    type: "animal_cat_revealed",
    payload: { policy: "awa_animal_dream_v1", actorId: 3, day: 1 },
  };
  if (false) {
    // @ts-expect-error Historical audience remains a readonly property.
    fear.audience = [];
    // @ts-expect-error Historical audience members cannot be edited through this contract.
    fear.audience.push(3);
  }
  void [noAudience, wrongPayload, noFoxAudience];
  expect(fear.audience).toEqual([2]);
  expect(cat).not.toHaveProperty("audience");
});

test("Cupid relation references neutral immutable metadata and player projection remains open", () => {
  const relation: LoversComponent = {
    actorId: 4,
    day: 1,
    policy: "netease_2017_cupid_follows_lovers_v1",
    pairIds: [2, 3],
    pairCamps: [Camp.Good, Camp.Wolf],
    groupId: "cupid_lovers",
    mixed: true,
  };
  const payload: EventPayloadMap["cupid_relation_resolved"] = relation;
  const projected: PlayerVisibleEvent = {
    seq: 5,
    type: "future_projected_event",
    payload: { target: 2, targetId: 3, custom: { original: "Raw {text}" } },
  };
  // @ts-expect-error The projected local sequence retains its numeric type.
  const badSequence: PlayerVisibleEvent = { seq: "5", type: "custom", payload: {} };
  if (false) {
    // @ts-expect-error Pair members remain readonly metadata rather than component writes.
    payload.pairIds[0] = 5;
    // @ts-expect-error The relation contains only the original enum-typed factions.
    const rawCamps: LoversComponent["pairCamps"] = ["good", "wolf"];
    void rawCamps;
  }
  void badSequence;
  expect(payload).toBe(relation);
  expect(projected.payload.custom).toEqual({ original: "Raw {text}" });
});

test("request context keeps four required fields and its original optional mutable and readonly extras", () => {
  const context: ActionRequestContext = {
    day: 1,
    stage: "witch",
    visible_events: [],
    turn_constraints: {},
  };
  const request: ActionRequest = {
    phase: Phase.Night,
    actorId: 2,
    allowedTools: ["use_potion"],
    context,
  };
  const extras: ActionRequestExtras = {
    wolf_target: null,
    shoot_candidates: [3, 4],
    sheriff_candidates: [3],
    allow_fallback: false,
    action_failure_policy: "error",
    retry_notice_message: { key: "common.player", parameters: { id: 2 } },
  };
  const timed: ActionRequest = { ...request, deadlineAtMs: 123 };
  // @ts-expect-error Day is a required common request field.
  const noDay: ActionRequestContext = { stage: "witch", visible_events: [], turn_constraints: {} };
  // @ts-expect-error Stage is a required common request field.
  const noStage: ActionRequestContext = { day: 1, visible_events: [], turn_constraints: {} };
  // @ts-expect-error Visible events are required even for the empty initial feed.
  const noFeed: ActionRequestContext = { day: 1, stage: "witch", turn_constraints: {} };
  // @ts-expect-error Turn constraints are required even when the constraint object is empty.
  const noConstraints: ActionRequestContext = { day: 1, stage: "witch", visible_events: [] };
  // @ts-expect-error Feature extras do not add an arbitrary string index.
  const unknownExtra: ActionRequestExtras = { invented_flag: true };
  // @ts-expect-error Strict action failure policy retains its single original literal.
  const changedFailure: ActionRequestExtras = { action_failure_policy: "fallback" };
  if (false) {
    // @ts-expect-error Private shoot candidates retain their readonly list type.
    extras.shoot_candidates?.push(5);
  }
  extras.sheriff_candidates?.push(4);
  context.visible_events.push({ seq: 1, type: "custom", payload: {} });
  void [noDay, noStage, noFeed, noConstraints, unknownExtra, changedFailure];
  expect(request).not.toHaveProperty("deadlineAtMs");
  expect(timed.deadlineAtMs).toBe(123);
  expect(extras.sheriff_candidates).toEqual([3, 4]);
  expect(context.visible_events).toHaveLength(1);
});

/**
 * Package unit contract for Animal Dream payload and audience data. Literal
 * per-type JSON rows independently preserve hidden/public classification, own
 * beauty history, causal source maps, pair policy limits and accepted legacy
 * scalar conditions. No state owner, vote tally, clock, callback or resolver is
 * loaded; parsing a fact never authorizes an action or commits a game effect.
 */
import { expect, test } from "bun:test";
import {
  ANIMAL_DREAM_EVENT_TYPES,
  animalDreamFactAudience,
  readAnimalDreamFact,
} from "@ai-werewolf-arena/game-contract/facts/animal-dream";
const policy = "awa_animal_dream_v1";
const base = { policy, day: 2 };
const actor = { ...base, actorId: 9 };

test("thirteen literal payload variants retain exact fields and copies", () => {
  const rows: ReadonlyArray<readonly [string, Record<string, unknown>]> = [
    ["animal_night_opened", base],
    ["animal_fox_chosen", { ...actor, targetId: null }],
    ["animal_fox_effect", { ...actor, targetId: 3, knifeBlocked: true, beautyBlocked: false }],
    ["animal_knife_notified", { ...actor, eligible: true }],
    [
      "animal_beauty_notified",
      {
        ...actor,
        charmAllowed: false,
        linkAllowed: false,
        targetId: null,
        lastActedDay: 2,
        history: [
          { day: 1, targetId: 3 },
          { day: 2, targetId: null },
        ],
      },
    ],
    ["animal_cat_revealed", actor],
    ["animal_puffer_revealed", { ...actor, reason: "knife_death" }],
    ["animal_puffer_decided", { ...actor, activate: false }],
    ["animal_puffer_targets", { ...actor, targetIds: [3, 4], round: 2 }],
    ["animal_wave_prepared", { ...base, phase: "night", proposedIds: [3], blockedCatId: null }],
    [
      "animal_wave_committed",
      { ...base, phase: "voting", deaths: [3], deathSources: { 3: ["exile"] } },
    ],
    ["animal_cat_expiry_prepared", { ...actor, unit: 2, unitKind: "skipped_day" }],
    ["animal_unit_completed", { ...base, unit: 2, kind: "exile" }],
  ];
  expect<unknown>(ANIMAL_DREAM_EVENT_TYPES).toEqual(rows.map(([type]) => type));
  for (const [type, input] of rows) {
    const fact = readAnimalDreamFact(type, input)!;
    expect<unknown>(fact).toEqual({ type, payload: input });
    expect(fact.payload).not.toBe(input);
    expect(readAnimalDreamFact(type, { ...input, extra: true })).toBeNull();
  }
});

test("public reveal stays distinct from actor notice and God settlement facts", () => {
  expect(animalDreamFactAudience("animal_cat_revealed")).toBe("public");
  expect(animalDreamFactAudience("animal_puffer_revealed")).toBe("public");
  for (const type of [
    "animal_fox_chosen",
    "animal_knife_notified",
    "animal_beauty_notified",
    "animal_puffer_decided",
  ] as const)
    expect(animalDreamFactAudience(type)).toBe("actor");
  for (const type of [
    "animal_wave_prepared",
    "animal_wave_committed",
    "animal_fox_effect",
    "animal_puffer_targets",
    "animal_unit_completed",
  ] as const)
    expect(animalDreamFactAudience(type)).toBe("god");
});

test("Fox starts atN2, but the reader does not infer policy implication between boolean flags", () => {
  expect(readAnimalDreamFact("animal_fox_chosen", { ...actor, day: 1, targetId: null })).toBeNull();
  expect(
    readAnimalDreamFact("animal_fox_effect", {
      ...actor,
      targetId: 3,
      knifeBlocked: false,
      beautyBlocked: true,
    }),
  ).not.toBeNull();
  expect(
    readAnimalDreamFact("animal_fox_effect", {
      ...actor,
      targetId: 3,
      knifeBlocked: "false",
      beautyBlocked: true,
    }),
  ).toBeNull();
});

test("Puffer target sets and wave sources keep exact original limits and legacy duplicate causes", () => {
  for (const targetIds of [[], [3, 3], Array.from({ length: 13 }, (_, i) => i + 1)])
    expect(
      readAnimalDreamFact("animal_puffer_targets", { ...actor, targetIds, round: 1 }),
    ).toBeNull();
  expect(
    readAnimalDreamFact("animal_puffer_targets", { ...actor, targetIds: [3], round: 3 }),
  ).toBeNull();
  const wave = { ...base, phase: "voting", deaths: [3], deathSources: { 3: ["exile", "exile"] } };
  expect(readAnimalDreamFact("animal_wave_committed", wave)).not.toBeNull();
  for (const deathSources of [{}, { 3: [] }, { 3: ["poison"] }, { 3: ["exile"], 4: ["charm"] }])
    expect(readAnimalDreamFact("animal_wave_committed", { ...wave, deathSources })).toBeNull();
});

test("Animal retains inclusive safe-integer maximum and large beauty history capacity", () => {
  expect(
    readAnimalDreamFact("animal_cat_revealed", { ...actor, actorId: Number.MAX_SAFE_INTEGER }),
  ).not.toBeNull();
  expect(
    readAnimalDreamFact("animal_cat_revealed", { ...actor, actorId: Number.MAX_SAFE_INTEGER + 1 }),
  ).toBeNull();
  const history = Array.from({ length: 129 }, (_, i) => ({ day: i + 1, targetId: null }));
  const notice = {
    ...actor,
    day: 129,
    charmAllowed: true,
    linkAllowed: true,
    targetId: null,
    lastActedDay: null,
    history,
  };
  expect(readAnimalDreamFact("animal_beauty_notified", notice)).not.toBeNull();
  expect(
    readAnimalDreamFact("animal_beauty_notified", {
      ...notice,
      history: [...history, { day: 129, targetId: null }],
    }),
  ).toBeNull();
});

test("unknown and accessor payloads reject without getter evaluation", () => {
  let reads = 0;
  const input = {
    ...base,
    get actorId() {
      reads++;
      return 9;
    },
  };
  expect(readAnimalDreamFact("legacy_unknown", input)).toBeNull();
  expect(readAnimalDreamFact("animal_cat_revealed", input)).toBeNull();
  expect(reads).toBe(0);
});

/**
 * Package unit contract for Awakened's complete event-branch reader.
 * Independent literal rows cover all eight branches, ID order, original day,
 * role/self and nullable checks. Unused values are ignored and never exported.
 * These descriptions never awaken a role, install abilities or authorize action;
 * the inert browser reflection boundary does not replace Node Proxy ingress.
 */
import { expect, test } from "bun:test";
import {
  AWAKENED_EVENT_TYPES,
  readAwakenedEventFact,
} from "@ai-werewolf-arena/game-contract/facts/awakened";

test("eight original ordered IDs stay unfrozen and each branch returns its selected fields", () => {
  expect(AWAKENED_EVENT_TYPES).toEqual([
    "awakened_inherited",
