      actorId: 99,
      day: 1,
      targetId: 999,
    }),
  ).toEqual({ actorId: 99, day: 1, targetId: 999 });
  expect(
    readTimeConsortReflectionFact("time_consort_reflected", {
      actorId: 99,
      day: 1,
      sourceId: 999,
      requestedId: 999,
      effectiveId: 999,
      kind: "check",
    }),
  ).toEqual({
    actorId: 99,
    day: 1,
    sourceId: 999,
