  for (const delta of [
    { actorId: 0 },
    { actorId: Number.MAX_SAFE_INTEGER },
    { day: 0 },
    { day: 2.5 },
    { targetId: -1 },
    { targetId: "3" },
    { targetId: NaN },
    { extra: true },
  ])
    expect(
      readTimeConsortChoiceFact("time_consort_lock_committed", { ...input, ...delta }),
    ).toBeNull();
  expect(
    readTimeConsortChoiceFact("time_consort_lock_committed", { actorId: 1, day: 2 }),
