/**
 * Responsibility: verify unit data-copy boundaries for shared fact payloads.
 * Literal shapes and original error codes are the oracle, independent of World
 * and feature settlement. Checks preserve depth/array limits, descriptor rejection,
 * plain-record output and the explicit inert-only browser Proxy precondition.
 */
import { expect, test } from "bun:test";
import { copyEventData } from "@ai-werewolf-arena/game-contract";

test("inert payload copies have detached dense arrays and null-prototype records", () => {
  const original = { pair: [1, 2], stock: 0, flags: { paid: false }, raw: "原文 {target}" };
  const copy = copyEventData(original) as typeof original;
  expect(copy).toEqual(original);
  expect(copy).not.toBe(original);
  expect(copy.pair).not.toBe(original.pair);
  expect(Object.getPrototypeOf(copy)).toBeNull();
  expect(Object.getPrototypeOf(copy.flags)).toBeNull();
  original.pair[0] = 3;
  expect(copy.pair).toEqual([1, 2]);
});

test("original depth and configurable array limits remain exact", () => {
  expect(() => copyEventData({ a: { b: { c: { d: {} } } } })).toThrow("event_fact_not_data");
  expect(copyEventData(Array(128).fill(1))).toHaveLength(128);
  expect(() => copyEventData(Array(129).fill(1))).toThrow("event_fact_array");
  expect(copyEventData(Array(129).fill(1), 129)).toHaveLength(129);
  expect(() => copyEventData([, 1])).toThrow("event_fact_array");
  expect(() => copyEventData(NaN)).toThrow("event_fact_not_data");
  expect(() => copyEventData({ value: undefined })).toThrow("event_fact_not_data");
});

test("accessors and non-data prototypes reject without evaluating getters", () => {
  let getters = 0;
  const accessor = Object.defineProperty({}, "target", {
    enumerable: true,
    get() {
      getters++;
      return 1;
    },
  });
  expect(() => copyEventData(accessor)).toThrow("event_fact_accessor");
  expect(getters).toBe(0);
  expect(() => copyEventData(new Date())).toThrow("event_fact_not_plain");
  expect(() => copyEventData({ [Symbol("field")]: 1 })).toThrow("event_fact_not_plain");
});

test("shared data copier does not claim Node zero-trap protection for arbitrary proxies", () => {
  let traps = 0;
  const value = new Proxy(
    { actorId: 1 },
    {
      getPrototypeOf(target) {
        traps++;
        return Reflect.getPrototypeOf(target);
      },
    },
  );
  expect(copyEventData(value)).toEqual({ actorId: 1 });
  expect(traps).toBeGreaterThan(0);
});

/**
 * Package unit / type contract for language-neutral message identities. The
 * independent oracle is the literal 1513-key sequence digest and endpoint keys
 * frozen from Git 2d36e4d, before migration. Fixtures are unknown key values and
 * serializable references; no dictionary, renderer, World or model is loaded.
 * Runtime parameter formatting remains a separate game-text responsibility.
 */
import { expect, test } from "bun:test";
import { createHash } from "node:crypto";
import {
  MESSAGE_IDS,
  isMessageKey,
  type MessageKey,
  type MessageRef,
} from "@ai-werewolf-arena/game-contract";

const fixedSequenceHash = "cd750ba72a9b5902562d650125797b2417126bdb82b2aaa199822b05cd22ec78";

test("the 1513 message IDs retain the exact fixed-commit sequence", () => {
  expect(MESSAGE_IDS).toHaveLength(1513);
  expect(new Set(MESSAGE_IDS).size).toBe(1513);
  expect(createHash("sha256").update(JSON.stringify(MESSAGE_IDS)).digest("hex")).toBe(
    fixedSequenceHash,
  );
  expect(MESSAGE_IDS[0]).toBe("replay.stage.animal_night_opened");
  expect(MESSAGE_IDS.at(-1)).toBe("prompt.config.badge_choice");
});

test("the canonical registry is frozen and key validation grants no inherited object names", () => {
  expect(Object.isFrozen(MESSAGE_IDS)).toBe(true);
  for (const value of [
    null,
    undefined,
    1,
    {},
    [],
    Symbol("message"),
    "",
    "constructor",
    "__proto__",
    "hasOwnProperty",
    "does.not.exist",
  ])
    expect(isMessageKey(value)).toBe(false);
  expect(isMessageKey("replay.stage.animal_night_opened")).toBe(true);
  expect(isMessageKey("prompt.config.badge_choice")).toBe(true);
  expect(isMessageKey("role.witch.state")).toBe(true);
  expect(isMessageKey("request.summary.exile_vote")).toBe(true);
  expect(isMessageKey("request.retry.exile_vote")).toBe(true);
});

test("unknown key guards do not inspect object properties or execute a Proxy", () => {
  let traps = 0;
  const value = new Proxy(
    {},
    {
      get() {
        traps++;
        return "common.player";
      },
      getPrototypeOf() {
        traps++;
        return Object.prototype;
      },
    },
  );
  expect(isMessageKey(value)).toBe(false);
  expect(traps).toBe(0);
});

test("closed key typing and optional readonly parameter shape preserve existing interfaces", () => {
  const key: MessageKey = "common.player";
  const omitted: MessageRef = { key: "common.none" };
  const numeric: MessageRef = { key, parameters: { id: 12 } };
  const raw = "苏茶茶\nExact custom text {role}";
  const original: MessageRef = { key: "role.generic.state", parameters: { role: raw } };
  // The DTO intentionally has no per-key parameter generic or formatting policy.
  const missingParameters: MessageRef = { key: "role.witch.state" };
  const extraParameters: MessageRef = { key: "common.none", parameters: { extra: "literal" } };
  const nonfinite: MessageRef = { key, parameters: { id: NaN } };
  // @ts-expect-error Unknown machine keys cannot become a MessageKey.
  const unknownKey: MessageKey = "does.not.exist";
  // @ts-expect-error References also retain the closed machine key set.
  const unknownReference: MessageRef = { key: "does.not.exist" };
  // @ts-expect-error Parameters retain the original string/number value contract.
  const booleanParameter: MessageRef = { key, parameters: { id: true } };
  if (false) {
    // @ts-expect-error Existing readonly parameter maps cannot be mutated through a reference.
    numeric.parameters!.id = 13;
  }
  void [unknownKey, unknownReference, booleanParameter, nonfinite];
  expect(omitted).toEqual({ key: "common.none" });
  expect(numeric.parameters).toEqual({ id: 12 });
  expect(JSON.parse(JSON.stringify(original))).toEqual(original);
  expect(original.parameters!.role).toBe(raw);
  expect(missingParameters).toEqual({ key: "role.witch.state" });
  expect(extraParameters.parameters).toEqual({ extra: "literal" });
});

